#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe coap-watch-a-resource-change. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site
printf '%s' 'setpoint=68' > site/thermostat.txt
printf '%s' 'setpoint=70' > new.txt
cat > observe.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Usage: sh observe.sh COAP_PORT HTTP_PORT HOW SECONDS. The gateway observes thermostat.txt with
# curl --coap-observe, writing each representation it is sent to seen.txt, a line each. Once it holds
# the first, the file is replaced with new.txt by HOW: coap (a CoAP PUT), http (an HTTP PUT) or
# delete (a CoAP DELETE). Then it waits at most SECONDS for the gateway to see the change and prints
# what the gateway saw.
coap="coap://127.0.0.1:$1/thermostat.txt"
rm -f seen.txt
curl -s -m 90 --coap-observe "$coap" -o seen.txt &
gateway=$!
tries=0
until [ -s seen.txt ]; do
  tries=$((tries + 1))
  if [ "$tries" -gt 20 ]; then echo "the gateway was not registered within 10 s" >&2; kill "$gateway"; exit 1; fi
  sleep 0.5
done
case "$3" in
  coap) curl -s -X PUT -d @new.txt "$coap" ;;
  http) curl -s -T new.txt "http://127.0.0.1:$2/thermostat.txt" ;;
  delete) curl -s -X DELETE "$coap"; wait "$gateway"; echo "the gateway ended by itself, exit $?"; cat seen.txt; exit 0 ;;
esac
tries=0
until [ "$(grep -c . seen.txt)" -ge 2 ]; do
  tries=$((tries + 1))
  if [ "$tries" -gt $(($4 * 2)) ]; then break; fi
  sleep 0.5
done
kill "$gateway"
cat seen.txt
if [ "$(grep -c . seen.txt)" -lt 2 ]; then echo "no change seen within $4 s"; fi
EOF
surl --directory site --allow-anonymous --allow-uploads coap://127.0.0.1:8080/ http://127.0.0.1:8081/ &
sleep 1
sh observe.sh 8080 8081 coap 10
kill $(jobs -p)
